import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel and C++ binding (inline extension)
# ----------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void mean_reduce_dim1_kernel(const scalar_t* __restrict__ input,
                                        scalar_t* __restrict__ output,
                                        int N, int K, int M) {
    int n = blockIdx.x;                                   // batch index
    int m = blockIdx.y * blockDim.x + threadIdx.x;        // dim2 index
    if (n >= N || m >= M) return;

    float sum = 0.0f;
    #pragma unroll 4
    for (int k = 0; k < K; ++k) {
        // index in row‑major (N, K, M) tensor
        int idx = ((n * K + k) * M) + m;
        sum += static_cast<float>(input[idx]);            // promote to fp32
    }
    // write fp16 mean
    output[n * M + m] = static_cast<scalar_t>(sum / static_cast<float>(K));
}

torch::Tensor mean_reduce_dim1(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 3, "input must be 3‑D");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");

    const int64_t N = input.size(0);
    const int64_t K = input.size(1);
    const int64_t M = input.size(2);

    auto output = torch::empty({N, M}, input.options());

    const int threads = 256;
    const dim3 blocks(N, (M + threads - 1) / threads);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "mean_reduce_dim1_cuda", ([&] {
        mean_reduce_dim1_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            static_cast<int>(N),
            static_cast<int>(K),
            static_cast<int>(M));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mean_reduce_dim1", &mean_reduce_dim1, "Mean reduction over dim=1 (fp16)");
}
'''

# Build the inline extension
_ext = load_inline(name='mean_reduce_dim1_ext',
                   cpp_sources=[src],
                   functions=['mean_reduce_dim1'],
                   verbose=False)

# ----------------------------------------------------------------------
# PyTorch model that uses the custom kernel
