    """
    Drop‑in replacement for the reference Model.
    Currently only supports reduction over dim=1 (the second dimension).
    """
    def __init__(self, dim: int):
        super().__init__()
        if dim != 1:
            raise NotImplementedError("Custom CUDA kernel only implements dim=1")
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Expect x to be CUDA fp16 tensor of shape (N, K, M)
